t=Text("FOUND HALF-NAKED IN THE SNOW",font_size=40,color=ORANGE).to_edge(UP,buff=0.4)
snow=Rectangle(width=12,height=2.2,color=WHITE,fill_color=WHITE,fill_opacity=0.15,stroke_width=0).move_to(DOWN*2.4)
def cloth(x,c,w):
    return Rectangle(width=w,height=0.5,color=c,fill_color=c,fill_opacity=0.7,stroke_width=3).move_to([x,-1.6,0])
items=VGroup(cloth(-4,RED,1.3),cloth(-1.5,BLUE,1.0),cloth(1.2,GREEN,1.2),cloth(3.8,ORANGE,0.9))
labs=VGroup(*[Text(n,font_size=26,color=WHITE).next_to(c,UP,buff=0.2) for n,c in zip(["COAT","GLOVES","SHIRT","HAT"],items)])
self.play(FadeIn(t),FadeIn(snow),run_time=0.8)
for c,l in zip(items,labs): self.play(FadeIn(c,shift=DOWN*0.4),FadeIn(l),run_time=0.6)
n=Text("CLOTHES LEFT BEHIND, OFTEN NEATLY",font_size=32,color=YELLOW).move_to(UP*0.8)
self.play(FadeIn(n),run_time=0.7); self.wait(1.5)

t=Text("A COLD HEART LOSES ITS RHYTHM",font_size=38,color=ORANGE).to_edge(UP,buff=0.4)
ax=Axes(x_range=[0,12,1],y_range=[-2,2,1],x_length=11,y_length=3.5,tips=False,axis_config={"color":GREY}).shift(DOWN*0.3)
def ecg(x):
    if x<6:
        p=x%2
        return 1.6 if 0.9<p<1.0 else (-0.5 if 1.0<=p<1.1 else 0.0)
    return 0.9*np.sin(9*x)*np.sin(3.1*x)
c=ax.plot(ecg,x_range=[0,12,0.01],color=GREEN,stroke_width=5,use_smoothing=False)
a=Text("NORMAL",font_size=30,color=GREEN).move_to(LEFT*3.2+UP*2)
b=Text("FIBRILLATION: CHAOS",font_size=30,color=RED).move_to(RIGHT*3+UP*2)
self.play(FadeIn(t),Create(ax),FadeIn(a),run_time=1)
self.play(Create(c),run_time=4,rate_func=linear)
self.play(FadeIn(b),run_time=0.5); self.wait(0.5)
